/**
 * Determines whether a given integer n is prime.
 * Uses the classic 6k ± 1 method which checks divisibility only
 * by numbers of the form 6k-1 and 6k+1 up to sqrt(n).
 * @param {number|bigint} n - The integer to test (must be >= 0).
 * @returns {boolean} true if n is prime, false otherwise.
 */
function isPrime(n) {
  // Support both Number and BigInt inputs
  if (typeof n === 'bigint') {
    if (n < 2n) return false;
    if (n === 2n || n === 3n) return true;
    if (n % 2n === 0n || n % 3n === 0n) return false;
    for (let i = 5n; i * i <= n; i += 6n) {
      if (n % i === 0n || n % (i + 2n) === 0n) return false;
    }
    return true;
  }

  // Number path (fast for < 2^53)
  if (n <= 1) return false;
  if (n <= 3) return true;
  if (n % 2 === 0 || n % 3 === 0) return false;
  for (let i = 5; i * i <= n; i += 6) {
    if (n % i === 0 || n % (i + 2) === 0) return false;
  }
  return true;
}

// -------------------- Test Suite --------------------
const assert = require('assert');

// Helper to run a single test and report nicely
function runTest(input, expected) {
  const result = isPrime(input);
  assert.strictEqual(result, expected, `isPrime(${input}) → ${result}, expected ${expected}`);
}

// Test cases – a mix of small, medium, large, Number and BigInt values
const testCases = [
  // Edge cases
  [0, false],
  [1, false],
  [2, true],
  [3, true],
  [4, false],
  // Typical numbers
  [5, true],
  [6, false],
  [7, true],
  [9, false],
  [11, true],
  [15, false],
  [17, true],
  [19, true],
  [20, false],
  // Larger primes/composites within safe Number range
  [97, true],
  [100, false],
  [7919, true], // 1000th prime
  [7920, false],
  [104729, true], // 10000th prime
  [104730, false],
  // Very large values using BigInt (beyond 2^53)
  [999999999999989n, true], // known prime
  [999999999999990n, false],
  [1234567891011121314n, false],
  [1234567891011121313n, false], // not prime, just to test BigInt path
];

console.log('Running Prime Checker Test Suite...');
let passed = 0;
